INSERT INTO "FertilizerCategory" ("id", "name", "slug", "nutrientProfile", "description", "applicationRole", "precautions", "createdAt", "updatedAt") VALUES ('899665b3-7e38-40ba-8ed3-2831cb8b9a7a', 'Urea (Neem Coated)', 'urea', '46% Nitrogen (N)', 'The primary source of concentrated solid nitrogen in Indian agriculture. Neem coating slows nitrification, significantly reducing ammonia volatilization and nitrate leaching.', 'Rapid vegetative growth, lush green foliage synthesis, protein formation', 'Do not apply in excessive doses; avoid applying on waterlogged soils without drainage; split applications into 2-3 intervals to avoid burning and lodging.', '2026-10-11T06:51:22.766Z', '2026-10-11T06:52:04.392Z') ON CONFLICT DO NOTHING;
INSERT INTO "FertilizerCategory" ("id", "name", "slug", "nutrientProfile", "description", "applicationRole", "precautions", "createdAt", "updatedAt") VALUES ('a4e58663-64d7-484a-bdee-a94c9825fb0c', 'DAP (Di-Ammonium Phosphate)', 'dap', '18% Nitrogen (N), 46% Phosphorus (P2O5)', 'High-analysis phosphorus fertilizer that delivers readily available water-soluble phosphate for early root development alongside initial starter nitrogen.', 'Strong seedling root proliferation, tillering vigor, early crop establishment', 'Always apply at or below seed depth (basal placement). Never broadcast on surface; avoid direct seed contact to prevent ammonia seed toxicity.', '2026-10-11T06:51:22.769Z', '2026-10-11T06:52:04.396Z') ON CONFLICT DO NOTHING;
INSERT INTO "FertilizerCategory" ("id", "name", "slug", "nutrientProfile", "description", "applicationRole", "precautions", "createdAt", "updatedAt") VALUES ('cbb41cb9-b88e-437d-997d-a6ff7fb75c44', 'SSP (Single Super Phosphate)', 'ssp', '16% P2O5, 11% Sulphur (S), 19% Calcium (Ca)', 'Ideal phosphatic fertilizer for oilseeds and pulses due to high elemental sulphur and calcium content, enhancing oil synthesis and nodule formation.', 'Oil percentage enhancement in groundnut & mustard, root nodulation in pulses', 'Apply at sowing time; keep stored away from excessive moisture as SSP can cake easily.', '2026-10-11T06:51:22.772Z', '2026-10-11T06:52:04.399Z') ON CONFLICT DO NOTHING;
INSERT INTO "FertilizerCategory" ("id", "name", "slug", "nutrientProfile", "description", "applicationRole", "precautions", "createdAt", "updatedAt") VALUES ('7513bf57-ba40-41b8-9107-7b0c303a1df4', 'MOP (Muriate of Potash / KCl)', 'mop', '60% Potash (K2O)', 'The standard potassium fertilizer essential for water regulation, enzymatic activation, resistance against pests/drought, and grain filling.', 'Drought tolerance, disease resilience, sturdy stalk formation, plump grain filling', 'Avoid in chloride-sensitive crops (like tobacco and high-salinity orchards); incorporate thoroughly during basal or first top-dress.', '2026-10-11T06:51:22.775Z', '2026-10-11T06:52:04.402Z') ON CONFLICT DO NOTHING;
INSERT INTO "FertilizerCategory" ("id", "name", "slug", "nutrientProfile", "description", "applicationRole", "precautions", "createdAt", "updatedAt") VALUES ('8f132e38-adf4-4040-a501-c99f08218b16', 'NPK Complex (10:26:26)', 'npk-10-26-26', '10% N, 26% P2O5, 26% K2O', 'Balanced compound fertilizer packed with high phosphorus and potash, particularly recommended for cotton, sugarcane, and potato.', 'Balanced nutrition promoting deep rooting, pest resistance, and fruit/boll sizing', 'Ensure proper soil moisture before and after application to maximize uptake.', '2026-10-11T06:51:22.778Z', '2026-10-11T06:52:04.405Z') ON CONFLICT DO NOTHING;
INSERT INTO "FertilizerCategory" ("id", "name", "slug", "nutrientProfile", "description", "applicationRole", "precautions", "createdAt", "updatedAt") VALUES ('a9355ab8-0491-436e-a5f5-1ff8ad27b89f', 'Water Soluble NPK (19:19:19)', 'npk-19-19-19', '19% N, 19% P, 19% K (100% Water Soluble)', 'Premium grade foliar and drip fertigation formula providing immediate plant-absorbable primary nutrients without soil fixation.', 'Instant vegetative pick-up, recovery after biotic stress, foliar correction', 'Use during early morning or late afternoon foliar spray; do not spray during harsh midday sun.', '2026-10-11T06:51:22.782Z', '2026-10-11T06:52:04.408Z') ON CONFLICT DO NOTHING;
INSERT INTO "FertilizerCategory" ("id", "name", "slug", "nutrientProfile", "description", "applicationRole", "precautions", "createdAt", "updatedAt") VALUES ('b8b6bb95-34a6-4d3f-ad59-c6a64ae57909', 'Zinc Sulphate Micronutrient (33% Zn)', 'zinc-sulphate', '33% Zinc (Zn), 15% Sulphur (S)', 'Crucial micronutrient addressing widespread zinc deficiency in Indian alkaline and calcareous soils (especially Gujarat and Gangetic plains).', 'Chlorophyll synthesis, auxin auxin hormone activation, preventing "Khaira" disease in rice and leaf mottling', 'CRITICAL: Never mix zinc sulphate directly with DAP or water-soluble phosphate fertilizers, as insoluble zinc phosphate will precipitate out.', '2026-10-11T06:51:22.785Z', '2026-10-11T06:52:04.411Z') ON CONFLICT DO NOTHING;
INSERT INTO "FertilizerCategory" ("id", "name", "slug", "nutrientProfile", "description", "applicationRole", "precautions", "createdAt", "updatedAt") VALUES ('82721375-9362-47dd-b016-79d9fc601e1c', 'Enriched Organic Vermicompost', 'vermicompost', '1.5-2.0% N, 1.0% P, 1.5% K + Beneficial Microflora', 'Aerobic earthworm castings rich in humic acids, beneficial soil microbes, and slow-release micronutrients that improve soil water holding capacity.', 'Soil structure improvement, microbial biomass activation, long-term fertility', 'Apply 1-2 tonnes per acre during summer ploughing / land preparation; maintain adequate moisture for biological activity.', '2026-10-11T06:51:22.788Z', '2026-10-11T06:52:04.414Z') ON CONFLICT DO NOTHING;
INSERT INTO "CropFertilizerGuidance" ("id", "cropSlug", "cropName", "state", "cropStage", "nutrientRequirement", "fertilizerCategoryId", "recommendedTiming", "applicationMethod", "guidanceText", "whyItMatters", "importantPrecautions", "sourceAuthority", "sourceUrl", "lastVerifiedDate", "status") VALUES ('6a57178c-9385-4c9c-99b3-75670740ada6', 'wheat', 'Wheat', 'Gujarat & Western India', 'Basal / Land Preparation', 'N: 60 kg, P2O5: 60 kg, K2O: 40 kg per ha', 'a4e58663-64d7-484a-bdee-a94c9825fb0c', 'At sowing time (placed 4-5 cm below seed)', 'Deep soil placement via ferti-seed drill', 'Apply full dose of Phosphorus (DAP/SSP) and Potash (MOP) alongside 1/3rd of total Nitrogen requirement at the time of sowing. Deep placement ensures the young crown roots can tap nutrients without surface volatilization.', 'Phosphorus is immobile in soil and directly fuels rapid initial embryonic root elongation and crown node anchoring.', 'Do not broadcast DAP on the soil surface; verify soil test report for available P prior to application to avoid luxury consumption.', 'Anand Agricultural University (AAU) / ICAR Directorate of Wheat Research', 'https://aau.in', '2026-10-11T06:51:22.792Z', 'verified') ON CONFLICT DO NOTHING;
INSERT INTO "CropFertilizerGuidance" ("id", "cropSlug", "cropName", "state", "cropStage", "nutrientRequirement", "fertilizerCategoryId", "recommendedTiming", "applicationMethod", "guidanceText", "whyItMatters", "importantPrecautions", "sourceAuthority", "sourceUrl", "lastVerifiedDate", "status") VALUES ('6107fc46-a98a-4c94-912b-40b04e35a22e', 'wheat', 'Wheat', 'Gujarat & Western India', 'Crown Root Initiation (CRI - 21 Days)', 'Nitrogen (N) 30 kg/ha', '899665b3-7e38-40ba-8ed3-2831cb8b9a7a', '21 to 25 days after sowing, just prior to first irrigation', 'Broadcasting uniform granules followed immediately by light irrigation', 'Top-dress 1/3rd of the remaining Nitrogen as Neem Coated Urea at the critical CRI stage. Irrigate the field promptly after application to incorporate urea into the root zone.', 'Crown roots formed during this stage determine the total number of effective tillers per plant and final spike density.', 'Avoid applying urea in standing water pools; broadcast on moist soil before turning on irrigation.', 'ICAR-IIWBR Karnal / Anand Agricultural University', 'https://iiwbr.icar.gov.in', '2026-10-11T06:51:22.797Z', 'verified') ON CONFLICT DO NOTHING;
INSERT INTO "CropFertilizerGuidance" ("id", "cropSlug", "cropName", "state", "cropStage", "nutrientRequirement", "fertilizerCategoryId", "recommendedTiming", "applicationMethod", "guidanceText", "whyItMatters", "importantPrecautions", "sourceAuthority", "sourceUrl", "lastVerifiedDate", "status") VALUES ('23053030-e8e7-44d8-bc01-33a32bf41538', 'cotton', 'Cotton (Bt Hybrid)', 'Gujarat (Saurashtra & Central)', 'Land Preparation & Basal', 'N: 40 kg, P2O5: 50 kg, K2O: 50 kg per ha', '8f132e38-adf4-4040-a501-c99f08218b16', 'At planting row preparation', 'Band placement 7-10 cm away from seed row', 'Apply 10:26:26 complex or DAP + MOP along with 10 tonnes of FYM/Vermicompost per hectare. In Gujarat black soils, band placement prevents phosphorus fixation in alkaline calcium compounds.', 'Bt cotton exhibits heavy early nutrient demand to sustain both vegetative branches and early sympodial fruiting branches.', 'Ensure soil moisture is sufficient; if soil zinc is below 0.6 ppm, apply Zinc Sulphate 25 kg/ha separately as basal.', 'Junagadh Agricultural University (JAU) & ICAR-CICR Nagpur', 'https://jau.in', '2026-10-11T06:51:22.801Z', 'verified') ON CONFLICT DO NOTHING;
INSERT INTO "CropFertilizerGuidance" ("id", "cropSlug", "cropName", "state", "cropStage", "nutrientRequirement", "fertilizerCategoryId", "recommendedTiming", "applicationMethod", "guidanceText", "whyItMatters", "importantPrecautions", "sourceAuthority", "sourceUrl", "lastVerifiedDate", "status") VALUES ('da716b43-fe6a-4a06-bd97-65768b451dd6', 'cotton', 'Cotton (Bt Hybrid)', 'Gujarat (Saurashtra & Central)', 'Squaring & Flowering (60-75 Days)', 'Nitrogen (N) 50 kg, Potash 25 kg + Foliar Boron', '899665b3-7e38-40ba-8ed3-2831cb8b9a7a', '60 to 75 days after sowing during square emergence', 'Split side-dressing in root zone followed by irrigation', 'Apply second split of Urea. Spray 1% 19:19:19 or 0.2% Boron (Solubor) if square drop is observed due to overcast or cloudy monsoon conditions.', 'Square and boll formation is the peak sink period; nutrient starvation now results in premature square shedding and lower ginning percentage.', 'Do not over-apply nitrogen, which causes excessive vegetative lushness attractive to sucking pests like jassids and whiteflies.', 'Navsari Agricultural University (NAU) / ICAR-CICR', 'https://nau.in', '2026-10-11T06:51:22.805Z', 'verified') ON CONFLICT DO NOTHING;
INSERT INTO "CropFertilizerGuidance" ("id", "cropSlug", "cropName", "state", "cropStage", "nutrientRequirement", "fertilizerCategoryId", "recommendedTiming", "applicationMethod", "guidanceText", "whyItMatters", "importantPrecautions", "sourceAuthority", "sourceUrl", "lastVerifiedDate", "status") VALUES ('f300131f-3d22-4670-8976-e835509337e8', 'groundnut', 'Groundnut (Kharif/Summer)', 'Gujarat (Saurashtra)', 'Land Preparation & Basal Sowing', 'N: 25 kg, P2O5: 50 kg, Sulphur: 20 kg per ha', 'cbb41cb9-b88e-437d-997d-a6ff7fb75c44', 'At last ploughing before furrow making', 'Soil broadcast and shallow harrowing incorporation', 'Single Super Phosphate (SSP) is preferred over DAP for groundnut because it naturally supplies 11% elemental Sulphur and 19% Calcium, which are vital for gynophore (peg) development and kernel oil accumulation.', 'Groundnut is a legume that fixes its own atmospheric nitrogen once nodules form; high phosphorus and sulphur are its true yield limiting nutrients.', 'Avoid heavy nitrogen basal applications, which suppress native Rhizobium nodule formation on the root tap system.', 'ICAR-Directorate of Groundnut Research (DGR) Junagadh', 'https://dgr.icar.gov.in', '2026-10-11T06:51:22.810Z', 'verified') ON CONFLICT DO NOTHING;
INSERT INTO "CropFertilizerGuidance" ("id", "cropSlug", "cropName", "state", "cropStage", "nutrientRequirement", "fertilizerCategoryId", "recommendedTiming", "applicationMethod", "guidanceText", "whyItMatters", "importantPrecautions", "sourceAuthority", "sourceUrl", "lastVerifiedDate", "status") VALUES ('d6770ac2-a199-436e-97b7-5ae75dd72e25', 'groundnut', 'Groundnut (Kharif/Summer)', 'Gujarat (Saurashtra)', 'Pegging to Pod Formation (40-50 Days)', 'Calcium (Ca) as Gypsum 250 kg/ha', NULL, '40 to 45 days after sowing during peg entry into soil', 'Band application along the crop rows followed by light earthing up', 'Apply agricultural gypsum (250 kg/ha) near the root zone. Calcium is directly absorbed by the developing subterranean pods rather than through the plant roots.', 'Calcium deficiency leads to "pops" (empty shells with missing kernels) and blackened plumules.', 'Apply gypsum only when soil is sufficiently moist; avoid disturbing entering pegs during weeding.', 'Junagadh Agricultural University (JAU)', 'https://jau.in', '2026-10-11T06:51:22.814Z', 'verified') ON CONFLICT DO NOTHING;
INSERT INTO "ProductCategory" ("id", "name", "slug", "description", "icon", "createdAt", "updatedAt") VALUES ('3c5649be-376c-45a3-a2f2-6abf957a8b04', 'Chemical Fertilizers', 'chemical-fertilizers', 'Govt-subsidized and regulated macro nutrient fertilizers for main field crops.', 'sprout', '2026-10-11T06:52:04.455Z', '2026-10-11T06:52:04.455Z') ON CONFLICT DO NOTHING;
INSERT INTO "ProductCategory" ("id", "name", "slug", "description", "icon", "createdAt", "updatedAt") VALUES ('fdd490a5-85f2-45c4-b5dd-01f9b6f5f50c', 'Water-Soluble & Foliar', 'water-soluble', '100% soluble fertigation formulas for drip systems and foliar sprays.', 'droplet', '2026-10-11T06:52:04.460Z', '2026-10-11T06:52:04.460Z') ON CONFLICT DO NOTHING;
INSERT INTO "ProductCategory" ("id", "name", "slug", "description", "icon", "createdAt", "updatedAt") VALUES ('72d37bee-48d1-4af8-b2e4-77dea4e2b5f2', 'Organic & Bio-Fertilizers', 'organic-bio', 'Earthworm compost, mycorrhiza, and bacterial consortia for living soil health.', 'leaf', '2026-10-11T06:52:04.464Z', '2026-10-11T06:52:04.464Z') ON CONFLICT DO NOTHING;
INSERT INTO "ProductCategory" ("id", "name", "slug", "description", "icon", "createdAt", "updatedAt") VALUES ('5c0dc483-53fb-444e-a6de-82a666591110', 'Micronutrients & Promoters', 'micronutrients', 'Zinc, Boron, Magnesium and bio-stimulants for targeted crop deficiencies.', 'sparkles', '2026-10-11T06:52:04.467Z', '2026-10-11T06:52:04.467Z') ON CONFLICT DO NOTHING;
